// 📁 src/pages/SubmissionSuccessPage.js
import React from 'react';
import { useNavigate } from 'react-router-dom';
import '../styles/SubmissionSuccess.css';

const SubmissionSuccessPage = () => {
  const navigate = useNavigate();
  // Sample issue ID - in real app you would get this from route params or state
  const issueId = '#12345'; 

  return (
    <div className="success-container">
      <div className="success-card">
        <h1>Issue Management System</h1>
        
        <div className="success-message">
          <p>Issue Submitted Successfully! ID: {issueId}</p>
        </div>

        <div className="button-group">
          <button 
            className="dashboard-btn"
            onClick={() => navigate('/dashboard')}
          >
            Return to Dashboard
          </button>
          <button 
            className="back-btn"
            onClick={() => navigate(-1)}
          >
            Back
          </button>
        </div>
      </div>
    </div>
  );
};

export default SubmissionSuccessPage;
